<script setup>
import {ref,onMounted,onBeforeUnmount,watch} from 'vue';
import * as echarts from 'echarts/core';
import {LineChart,BarChart,PieChart,RadarChart,GaugeChart,ScatterChart,HeatmapChart,FunnelChart,TreemapChart,SankeyChart} from 'echarts/charts';
import {TooltipComponent,GridComponent,LegendComponent,RadarComponent,VisualMapComponent,TitleComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
echarts.use([LineChart,BarChart,PieChart,RadarChart,GaugeChart,ScatterChart,HeatmapChart,FunnelChart,TreemapChart,SankeyChart,TooltipComponent,GridComponent,LegendComponent,RadarComponent,VisualMapComponent,TitleComponent,CanvasRenderer]);
const props=defineProps({node:Object,rows:Array,theme:Object,playing:Boolean});const emit=defineEmits(['action']);const host=ref();let chart,observer,pending;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function option(){
 const n=props.node,p=n.props,design=p.chartDesign||'default',fields=n.data.fields,r=props.rows||[],names=r.map(v=>String(v[fields.name]??'')),values=r.map(v=>Number(v[fields.value])||0),secondary=r.map(v=>Number(v[fields.secondary])||0),color=n.style.accent||props.theme.accent,palette=p.chartPalette==='mono'?[color]:props.theme.palette,text=props.theme.muted,axis={axisLine:{show:false},axisTick:{show:false},axisLabel:{color:text,fontSize:11*n.style.fontSize/14,margin:12,hideOverlap:true},splitLine:{show:p.grid,lineStyle:{color:props.theme.text+'0c',type:'dashed'}}};
 let base={animation:props.playing&&!reduced,animationDuration:650,color:palette,textStyle:{fontFamily:n.style.fontFamily||'Inter,PingFang SC,sans-serif',color:text},tooltip:{trigger:'axis',backgroundColor:props.theme.panel,borderColor:color+'33',textStyle:{color:props.theme.text,fontSize:12},confine:true},grid:{top:16,left:10,right:12,bottom:8,containLabel:true},legend:{show:p.legend,bottom:0,right:8,textStyle:{color:text,fontSize:10*n.style.fontSize/14},itemWidth:12,itemHeight:5},xAxis:{...axis,type:'category',data:names,boundaryGap:false},yAxis:{...axis,type:'value',splitNumber:3},series:[]};
 if(p.legend)base.grid.bottom=30;
 if(n.h<260){base.grid.top=8;base.yAxis.splitNumber=2;}
 if(n.h<200){base.yAxis.show=false;base.grid.left=0;base.grid.right=8;base.grid.top=4;base.grid.bottom=p.legend?24:4;}
 const line=(values,name,c)=>({name,type:'line',data:values,smooth:p.smooth,showSymbol:false,lineStyle:{width:2,color:c},itemStyle:{color:c},...(n.type==='area'?{areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:c+'48'},{offset:1,color:c+'00'}])}}:{})});
 if(['line','area'].includes(n.type)){base.series=[line(values,p.seriesName,color),...(secondary.some(v=>v)?[line(secondary,p.secondaryName,palette[1]||color)]:[])];}
 if(['bar','stack','hbar'].includes(n.type)){base.xAxis.boundaryGap=true;base.series=[{name:p.seriesName,type:'bar',barMaxWidth:18,stack:n.type==='stack'?'total':undefined,data:values,itemStyle:{borderRadius:n.type==='stack'?0:[3,3,0,0],color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color},{offset:1,color:color+'44'}])}}];if(n.type==='stack')base.series.push({name:p.secondaryName,type:'bar',stack:'total',data:secondary,barMaxWidth:18,itemStyle:{color:palette[1]}});if(n.type==='hbar'){base.xAxis={...axis,type:'value',show:false};base.yAxis={...axis,type:'category',inverse:true,data:names,splitLine:{show:false}};base.series[0].showBackground=true;base.series[0].backgroundStyle={color:props.theme.text+'08',borderRadius:3};base.series[0].itemStyle={color,borderRadius:3};base.series[0].label={show:true,position:'right',fontSize:11,color:props.theme.text};base.grid.right=42;base.legend.show=false;}}
 const categorical=()=>{delete base.xAxis;delete base.yAxis;delete base.grid;base.tooltip.trigger='item';};
 if(['donut','pie'].includes(n.type)){categorical();const total=values.reduce((a,b)=>a+b,0);base.legend={show:p.legend,orient:'vertical',right:0,top:'middle',textStyle:{color:text,fontSize:11},itemWidth:7,itemHeight:7,itemGap:14};base.series=[{type:'pie',radius:n.type==='donut'?['58%','72%']:['20%','74%'],roseType:n.type==='pie'?'area':undefined,center:[p.legend?'32%':'50%','50%'],avoidLabelOverlap:true,label:{show:false},itemStyle:{borderColor:props.theme.panel,borderWidth:4,borderRadius:4},data:values.map((value,i)=>({name:names[i],value}))}];if(n.type==='donut')base.title={text:p.centerValue||total.toLocaleString(),subtext:p.centerLabel||'设备总数',left:p.legend?'30%':'48%',top:'37%',textAlign:'center',textStyle:{fontSize:25,fontWeight:500,color:props.theme.text},subtextStyle:{fontSize:10,color:text}};}
 if(n.type==='radar'){categorical();base.radar={indicator:names.map(name=>({name,max:p.radarMax||Math.max(...values)*1.25||100})),axisName:{color:text,fontSize:11},splitLine:{lineStyle:{color:props.theme.text+'12'}},splitArea:{areaStyle:{color:[props.theme.text+'03','transparent']}},axisLine:{lineStyle:{color:props.theme.text+'12'}}};base.series=[{type:'radar',data:[{name:p.seriesName,value:values}],lineStyle:{width:2},symbolSize:3,areaStyle:{opacity:.16}}];base.legend.show=false;}
 if(n.type==='gauge'){categorical();base.series=[{type:'gauge',radius:'88%',startAngle:220,endAngle:-40,min:0,max:100,progress:{show:true,width:10,roundCap:true},axisLine:{lineStyle:{width:10,color:[[1,props.theme.text+'10']]}},axisTick:{show:false},splitLine:{show:false},axisLabel:{color:text,distance:18,fontSize:9},pointer:{show:false},anchor:{show:false},detail:{valueAnimation:true,color:props.theme.text,fontSize:36,offsetCenter:[0,'5%'],formatter:'{value}%'},title:{show:false},data:[{value:Math.min(100,r.length?values[0]:p.value??78)}]}];base.legend.show=false;}
 if(n.type==='scatter'){base.xAxis={...axis,type:'value'};base.series=[{type:'scatter',symbolSize:v=>Math.max(8,Math.min(32,v[1]/10)),itemStyle:{opacity:.7},data:r.map((v,i)=>[Number(v.x??i*16+4),Number(v[fields.value])||0])}];base.legend.show=false;}
 if(n.type==='heatmap'){base.xAxis={...axis,type:'category',data:p.xCategories||['周一','周二','周三','周四','周五','周六','周日'],splitLine:{show:false}};base.yAxis={...axis,type:'category',data:p.yCategories||['凌晨','上午','中午','下午','夜间'],splitLine:{show:false}};base.visualMap={show:false,min:0,max:100,inRange:{color:[props.theme.panel,color]}};base.series=[{type:'heatmap',data:r.some(v=>v.x!==undefined&&v.y!==undefined)?r.map(v=>[Number(v.x),Number(v.y),Number(v[fields.value])||0]):Array.from({length:35},(_,i)=>[i%7,Math.floor(i/7),values[i%values.length]%100||0]),itemStyle:{borderColor:props.theme.bg,borderWidth:3}}];base.legend.show=false;}
 if(n.type==='funnel'){categorical();base.series=[{type:'funnel',left:'10%',top:8,bottom:12,width:'80%',gap:4,sort:'descending',label:{color:props.theme.text,fontSize:11,position:'inside'},itemStyle:{borderWidth:0},data:values.map((value,i)=>({name:names[i],value}))}];base.legend.show=false;}
 if(n.type==='treemap'){categorical();base.series=[{type:'treemap',width:'100%',height:'100%',roam:false,breadcrumb:{show:false},label:{color:props.theme.text,fontSize:12},itemStyle:{borderColor:props.theme.bg,borderWidth:3,gapWidth:3},data:r.map(v=>({name:String(v[fields.name]),value:Number(v[fields.value]),children:v.children}))}];base.legend.show=false;}
 if(n.type==='sankey'){categorical();const links=r.filter(v=>v.source&&v.target).map(v=>({source:String(v.source),target:String(v.target),value:Number(v[fields.value])||1}));const actual=links.length?links:names.slice(1).map((name,i)=>({source:names[0]||'来源',target:name,value:values[i+1]}));base.series=[{type:'sankey',left:12,right:70,top:18,bottom:18,nodeWidth:8,nodeGap:24,emphasis:{focus:'adjacency'},data:[...new Set(actual.flatMap(l=>[l.source,l.target]))].map(name=>({name})),links:actual,lineStyle:{color:'source',curveness:.5,opacity:.2},label:{color:text,fontSize:11},itemStyle:{borderWidth:0}}];base.legend.show=false;}

 if(design==='command'){
  base.series.forEach(s=>{if(s.type==='line')s.lineStyle={...s.lineStyle,width:2,shadowColor:color+'90',shadowBlur:8};if(s.type==='bar'){s.itemStyle={...s.itemStyle,borderRadius:0};s.barMaxWidth=n.type==='hbar'?13:16;}});
  if(n.type==='donut'){base.series[0].padAngle=5;base.series[0].itemStyle={borderWidth:0,borderRadius:0};base.series[0].radius=['62%','72%'];}
 }
 if(design==='botanical'){
  base.series.forEach(s=>{if(s.type==='bar'){s.barMaxWidth=28;s.itemStyle={...s.itemStyle,borderRadius:[10,10,2,2],color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:palette[1]||color},{offset:1,color:color+'70'}])};}if(s.type==='radar'){s.areaStyle={opacity:.3};s.lineStyle={width:1.6,color};s.symbol='circle';s.symbolSize=5;}});
  if(n.type==='radar')base.radar={...base.radar,radius:'64%',center:['50%','53%'],shape:'circle',splitNumber:3};
  if(['line','area'].includes(n.type))base.series.forEach((s,i)=>{s.lineStyle={...s.lineStyle,width:i?1:2};if(i)s.lineStyle.type='dashed';});
 }
 if(design==='precision'){
  base.series.forEach(s=>{if(s.type==='bar'){s.itemStyle={...s.itemStyle,borderRadius:0,color:s.name===p.secondaryName?palette[2]:color};s.barMaxWidth=24;}if(s.type==='line')s.smooth=false;});
  if(n.type==='gauge'){const s=base.series[0];s.startAngle=225;s.endAngle=-45;s.radius='83%';s.progress={show:true,width:8,roundCap:false};s.axisLine.lineStyle.width=8;s.splitNumber=5;s.axisTick={show:true,distance:-18,length:3,lineStyle:{color:color+'55',width:1}};s.splitLine={show:true,distance:-20,length:7,lineStyle:{color:color+'80',width:1}};s.axisLabel={color:text,distance:14,fontSize:9};s.detail={...s.detail,fontSize:33,offsetCenter:[0,'5%']};s.title={show:true,offsetCenter:[0,'38%'],color:text,fontSize:10};s.data[0].name=p.centerLabel||r[0]?.name||'运行指数';}
  if(n.type==='heatmap'){base.grid={top:5,left:5,right:2,bottom:2,containLabel:true};base.visualMap.inRange.color=[props.theme.panel,'#706244',color];base.series[0].itemStyle={borderColor:props.theme.panel,borderWidth:4,borderRadius:2};}
  if(n.type==='sankey'){base.series[0].nodeWidth=5;base.series[0].nodeGap=14;base.series[0].lineStyle={color:'gradient',curveness:.45,opacity:.33};base.series[0].label.fontSize=10;base.series[0].levels=[{depth:0,label:{position:'right'}},{depth:1,label:{position:'right'}},{depth:2,label:{position:'left'}}];}
 }
 if(design==='orbital'){
  base.series.forEach(s=>{if(s.type==='line'){s.smooth=.45;s.lineStyle={...s.lineStyle,width:2};s.areaStyle={color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:color+'26'},{offset:1,color:color+'00'}])};}if(s.type==='bar'&&n.type==='hbar'){s.barMaxWidth=8;s.itemStyle={borderRadius:6,color:new echarts.graphic.LinearGradient(0,0,1,0,[{offset:0,color:palette[1]},{offset:1,color}])};}});
  if(n.type==='donut'){base.series[0].radius=['66%','74%'];base.series[0].padAngle=6;base.series[0].itemStyle={borderWidth:0,borderRadius:8};base.title.textStyle.fontSize=23;base.legend.itemGap=16;}
 }
 if(n.type==='gauge'){const s=base.series[0],height=host.value?.clientHeight||200;s.detail.fontSize=Math.min(s.detail.fontSize,Math.max(16,height*.16));s.axisLabel.show=height>150;s.title.show=s.title.show&&height>130;}
 return base;
}
function update(){cancelAnimationFrame(pending);pending=requestAnimationFrame(()=>chart?.setOption(option(),{notMerge:true,lazyUpdate:true}));}
onMounted(()=>{chart=echarts.init(host.value,null,{renderer:'canvas',devicePixelRatio:Math.min(devicePixelRatio,1.5)});chart.on('click',e=>emit('action','click',{...e.data,name:e.name,value:e.value}));chart.on('mouseover',e=>emit('action','hover',{...e.data,name:e.name,value:e.value}));observer=new ResizeObserver(()=>{chart?.resize();update();});observer.observe(host.value);update();});watch(()=>[props.node.props,props.node.style,props.rows,props.theme,props.playing],update,{deep:true});onBeforeUnmount(()=>{cancelAnimationFrame(pending);observer?.disconnect();chart?.dispose();});
</script>
<template><div ref="host" class="aw-chart" role="img" :aria-label="node.props.title+'图表'"></div></template>
